from datetime import date, timedelta
# feriados completos extraídos de library/calendario_forense_campinas.md (período relevante)
HOLIDAYS = {date(2026,11,20), date(2026,12,8), date(2026,12,24), date(2026,12,25),
            date(2026,12,31), date(2027,1,1), date(2027,2,8), date(2027,2,9)}
RECESSO = [date(2026,12,20)+timedelta(days=i) for i in range(32)]  # 20/12/2026 a 20/01/2027 incl.
def is_b(d):
    return d not in RECESSO and d.weekday()<5 and d not in HOLIDAYS
def next_b(d):
    d+=timedelta(days=1)
    while not is_b(d): d+=timedelta(days=1)
    return d
def count(inicio, dias):
    d=inicio; n=0
    while True:
        if is_b(d):
            n+=1
            if n==dias: return d
        d+=timedelta(days=1)

pub1 = next_b(date(2026,11,19)); ini1 = next_b(pub1)
pub2 = next_b(date(2026,12,10)); ini2 = next_b(pub2)
print("citacao   : publi", pub1, "| ini", ini1, "| contestacao", count(ini1,15))
print("sentenca  : publi", pub2, "| ini", ini2, "| embargos", count(ini2,5), "| apelacao", count(ini2,15))
print("condicionada (referência, 15 d.u. a partir de 19/12/2026):", count(date(2026,12,19),15))
print("dias do recesso:", len(RECESSO), "| 20/12/2026:", RECESSO[0], "| 20/01/2027:", RECESSO[-1])
EOF"}

